(3138947, 439203, 33542, '<td valign="top">There''s a yellow color cast to this picture - you can correct this in Photoshop, if you''ve got it.</td>', 'There''s a yellow color cast to this picture - you can correct this in Photoshop, if you''ve got it.', '2006-12-21 12:19:20.000000', NULL, 1),
(3138949, 440490, 56254, '<td valign="top">I like the grungy feel of this photo ... the tilted compositon makes me feel like I''m gonna fall off of my chair ...</td>', 'I like the grungy feel of this photo ... the tilted compositon makes me feel like I''m gonna fall off of my chair ...', '2006-12-21 12:19:51.000000', NULL, 1),
(3138952, 438357, 33542, '<td valign="top">I don''t like the extremely shallow DOF.</td>', 'I don''t like the extremely shallow DOF.', '2006-12-21 12:20:46.000000', NULL, 1),
(3138954, 440514, 56254, '<td valign="top">I''d like to see the contrast boosted just a bit here ... great composition and subject ... the wall anchors really balance the window out ...</td>', 'I''d like to see the contrast boosted just a bit here ... great composition and subject ... the wall anchors really balance the window out ...', '2006-12-21 12:20:53.000000', NULL, 1),
(3138956, 439053, 33542, '<td valign="top">Would have been more effective with newer, crisper money, IMO.</td>', 'Would have been more effective with newer, crisper money, IMO.', '2006-12-21 12:21:35.000000', NULL, 1),
(3138957, 438560, 66127, '<td valign="top">nice capture with good lighting,<br/>but i dont see the paranoia</td>', 'nice capture with good lighting,but i dont see the paranoia', '2006-12-21 12:21:48.000000', NULL, 1),
(3138958, 440564, 56254, '<td valign="top">it''s a bit bright on my monitor ... good composition though ...</td>', 'it''s a bit bright on my monitor ... good composition though ...', '2006-12-21 12:21:52.000000', NULL, 1),
(3138960, 439273, 56254, '<td valign="top">very cool ... where did you find one of those?</td>', 'very cool ... where did you find one of those?', '2006-12-21 12:22:20.000000', NULL, 1),
