(3139051, 439486, 56254, '<td valign="top">horizon is tilted a bit ...</td>', 'horizon is tilted a bit ...', '2006-12-21 12:47:59.000000', NULL, 1),
(3139055, 440670, 33542, '<td valign="top">The white at the top left and right is a bit distracting - it keeps us from seeing the sides of the box.</td>', 'The white at the top left and right is a bit distracting - it keeps us from seeing the sides of the box.', '2006-12-21 12:48:50.000000', NULL, 1),
