(3139065, 440316, 33542, '<td valign="top">Fuzzy. USM might have helped a bit, but it would still be a little fuzzy.</td>', 'Fuzzy. USM might have helped a bit, but it would still be a little fuzzy.', '2006-12-21 12:50:58.000000', NULL, 1),
