(3139590, 438942, 33542, '<td valign="top">There''s definitely some noise in the picture - might have been better with a quick NeatImage run - but the setting is very beautiful.</td>', 'There''s definitely some noise in the picture - might have been better with a quick NeatImage run - but the setting is very beautiful.', '2006-12-21 15:57:07.000000', NULL, 1),
(3139600, 440632, 33542, '<td valign="top">There are aspects of this picture I really like - for instance the shadows of the window panes across the wall. I wish there weren''t so much reflection making it impossible to see the entire mural. And the cars outside aren''t stellar, but not much you can do about that in basic - at least it was hazy.</td>', 'There are aspects of this picture I really like - for instance the shadows of the window panes across the wall. I wish there weren''t so much reflection making it impossible to see the entire mural. And the cars outside aren''t stellar, but not much you can do about that in basic - at least it was hazy.', '2006-12-21 15:59:23.000000', NULL, 1),
(3139602, 440644, 33542, '<td valign="top">amusing title</td>', 'amusing title', '2006-12-21 15:59:39.000000', NULL, 1),
