(3140441, 440037, 9690, '<td valign="top">Sooooo coooool</td>', 'Sooooo coooool', '2006-12-21 21:48:25.000000', NULL, 1),
(3140446, 439373, 9690, '<td valign="top">Wonderful.  And one of my favorite Floyd songs... although it RARELY crops up.  10</td>', 'Wonderful.  And one of my favorite Floyd songs... although it RARELY crops up.  10', '2006-12-21 21:50:40.000000', NULL, 1),
(3140453, 440654, 9690, '<td valign="top">Wonderful Floyd pic.  You really should have had a song from the Wall, though.  I believe "Waiting for the Worms" is where the hammers are featured in the movie.  I have to give it a 9 instead of a 10 for just that fact.</td>', 'Wonderful Floyd pic.  You really should have had a song from the Wall, though.  I believe "Waiting for the Worms" is where the hammers are featured in the movie.  I have to give it a 9 instead of a 10 for just that fact.', '2006-12-21 21:52:33.000000', NULL, 1),
(3140564, 440327, 7628, '<td valign="top">Wonderful! Very Magritte-like image: makes you ask, what? where? why? I like the balance of composition, the use of silhouette, and the creative use of plastic gloves!  Nice mutted colors.  I can''t decide if I''d prefer the line of the shore to be parallel with the horizon, or if having it at a relative slant helps make the viewer feel unsettled - which is certainly the effect of the song! 9</td>', 'Wonderful! Very Magritte-like image: makes you ask, what? where? why? I like the balance of composition, the use of silhouette, and the creative use of plastic gloves!  Nice mutted colors.  I can''t decide if I''d prefer the line of the shore to be parallel with the horizon, or if having it at a relative slant helps make the viewer feel unsettled - which is certainly the effect of the song! 9', '2006-12-21 22:29:35.000000', NULL, 1),
(3140565, 440605, 7628, '<td valign="top">Zoomdak - who else? Gorgeous sky, color, eerie silhouettes of the rocks.  Lost for words indeed.  The image is very true to the lyrics:<br/>Engulfed in a fever of spite<br/>Beyond your tunnel vision reality fades<br/>Like shadows into the night<br/>9</td>', 'Zoomdak - who else? Gorgeous sky, color, eerie silhouettes of the rocks.  Lost for words indeed.  The image is very true to the lyrics:Engulfed in a fever of spiteBeyond your tunnel vision reality fadesLike shadows into the night9', '2006-12-21 22:29:39.000000', NULL, 1),
(3140576, 438190, 66384, '<td valign="top">This is absolutely fabulous! 10</td>', 'This is absolutely fabulous! 10', '2006-12-21 22:33:27.000000', NULL, 1),
