(3144151, 440183, 24744, '<td valign="top">Probably the most creative and carefully done entry in this contest - hope to see it ribbon :)</td>', 'Probably the most creative and carefully done entry in this contest - hope to see it ribbon :)', '2006-12-23 06:39:38.000000', NULL, 1),
(3144165, 439966, 3087, '<td valign="top">I like the idea and the actual image itself with it''s great eye contact and close crop is interesting but I don''t like the processing at all. Too polarised and smoothed out for my preferences.</td>', 'I like the idea and the actual image itself with it''s great eye contact and close crop is interesting but I don''t like the processing at all. Too polarised and smoothed out for my preferences.', '2006-12-23 07:03:06.000000', NULL, 1),
(3144168, 440590, 3087, '<td valign="top">Great idea! I think it would have worked even better if the upper torso were also covered in mud - the hairy skin detracts somewhat from the "muddy" face. The composition works well. I''m not about the lighting - seems a touch too dark and orangey to me.</td>', 'Great idea! I think it would have worked even better if the upper torso were also covered in mud - the hairy skin detracts somewhat from the "muddy" face. The composition works well. I''m not about the lighting - seems a touch too dark and orangey to me.', '2006-12-23 07:04:48.000000', NULL, 1),
(3144169, 439422, 3087, '<td valign="top">Dangerous? I don''t know! But definitely scary! Simple idea though it portrays "demented" more strongly than "dangerous" to me. The lighting/ shadow doesn''t quite work for me - the reflected light on the knife is too bright and the shadows around her eyes and neck too harsh for my preferences.</td>', 'Dangerous? I don''t know! But definitely scary! Simple idea though it portrays "demented" more strongly than "dangerous" to me. The lighting/ shadow doesn''t quite work for me - the reflected light on the knife is too bright and the shadows around her eyes and neck too harsh for my preferences.', '2006-12-23 07:06:13.000000', NULL, 1),
(3144170, 439254, 3087, '<td valign="top">Coo! I''m intrigued by the technique behind this one! Kind of eery! :o)</td>', 'Coo! I''m intrigued by the technique behind this one! Kind of eery! :o)', '2006-12-23 07:07:15.000000', NULL, 1),
(3144171, 440456, 3087, '<td valign="top">Great choice of lyric and I love the choice of image! The wild hair, sullen but defiant expression and smudged make-up on a face that hasn''t had the skin neat-imaged to plasticine all works fantastically well to portray a somewhat deranged individual!</td>', 'Great choice of lyric and I love the choice of image! The wild hair, sullen but defiant expression and smudged make-up on a face that hasn''t had the skin neat-imaged to plasticine all works fantastically well to portray a somewhat deranged individual!', '2006-12-23 07:08:51.000000', NULL, 1),
(3144172, 439355, 3087, '<td valign="top">Wow, that IS dark! I like the way you''ve obscured much of the face - that really turns a standard portrait on it''s head - the hair all over hte place and the bright white of the teeth against the black of the hair and shadows - all works well. Not keen on the border but the core image I do like.</td>', 'Wow, that IS dark! I like the way you''ve obscured much of the face - that really turns a standard portrait on it''s head - the hair all over hte place and the bright white of the teeth against the black of the hair and shadows - all works well. Not keen on the border but the core image I do like.', '2006-12-23 07:11:20.000000', NULL, 1),
(3144174, 440245, 3087, '<td valign="top">An intriguing picture - nice compostion leaving so much empty sky balances the figure in the lower corner well. I think I''d prefer if the figure were facing into the frame rather than out of it but otherwise great. Feels a bit soft on the silhouette though - is that just motion blur?</td>', 'An intriguing picture - nice compostion leaving so much empty sky balances the figure in the lower corner well. I think I''d prefer if the figure were facing into the frame rather than out of it but otherwise great. Feels a bit soft on the silhouette though - is that just motion blur?', '2006-12-23 07:12:59.000000', NULL, 1),
(3144175, 438942, 3087, '<td valign="top">Lovely capture of mist over the water - like the canoeist focal point and the framing provided by the bridge and it''s reflection.</td>', 'Lovely capture of mist over the water - like the canoeist focal point and the framing provided by the bridge and it''s reflection.', '2006-12-23 07:14:04.000000', NULL, 1),
(3144176, 440487, 3087, '<td valign="top">Wow, what a cool location! I like your masked model - all very intriguing.</td>', 'Wow, what a cool location! I like your masked model - all very intriguing.', '2006-12-23 07:15:34.000000', NULL, 1),
(3144177, 440250, 3087, '<td valign="top">A really interesting abstract with some interesting colours and textures. Like it.</td>', 'A really interesting abstract with some interesting colours and textures. Like it.', '2006-12-23 07:17:51.000000', NULL, 1),
(3144178, 440040, 57886, '<td valign="top">Great colors and a good capture of the moon. .. nice closure to the title :o) Good luck..</td>', 'Great colors and a good capture of the moon. .. nice closure to the title :o) Good luck..', '2006-12-23 07:19:08.000000', NULL, 1),
(3144181, 440642, 57886, '<td valign="top">Nice DOF.. Nice pic, good luck :o)</td>', 'Nice DOF.. Nice pic, good luck :o)', '2006-12-23 07:20:07.000000', NULL, 1),
(3144183, 440183, 3087, '<td valign="top">Clever idea and very strong visual message. Is there actually a "Waters departing" lyric or are you just stretching it a little by pointing out this was the album during which Roger Waters left the band? Anyway, as I''m not voting, just commenting, my ignorance doesn''t make a difference either way! Would make a good stock image for drought and over use of water, I think.</td>', 'Clever idea and very strong visual message. Is there actually a "Waters departing" lyric or are you just stretching it a little by pointing out this was the album during which Roger Waters left the band? Anyway, as I''m not voting, just commenting, my ignorance doesn''t make a difference either way! Would make a good stock image for drought and over use of water, I think.', '2006-12-23 07:21:15.000000', NULL, 1),
(3144185, 440565, 3087, '<td valign="top">Nice idea but the lighting doesn''t work well for me.</td>', 'Nice idea but the lighting doesn''t work well for me.', '2006-12-23 07:22:31.000000', NULL, 1),
(3144187, 440037, 3087, '<td valign="top">Coo! Great reflections image, wonderful colours and composition. Very intriguing too. Really like this! One of my favourites in the challenge.</td>', 'Coo! Great reflections image, wonderful colours and composition. Very intriguing too. Really like this! One of my favourites in the challenge.', '2006-12-23 07:23:00.000000', NULL, 1),
(3144189, 440343, 3087, '<td valign="top">Appropriately odd, that''s for sure! So how did you get your hands on the cage?!</td>', 'Appropriately odd, that''s for sure! So how did you get your hands on the cage?!', '2006-12-23 07:23:33.000000', NULL, 1),
(3144191, 440649, 3087, '<td valign="top">Cool! Very Narnia! Like it!</td>', 'Cool! Very Narnia! Like it!', '2006-12-23 07:24:36.000000', NULL, 1),
(3144192, 440530, 3087, '<td valign="top">Lovely portrait - love the use of fairy lights for both colour, oddity and lighting! Nice use of negative space too.</td>', 'Lovely portrait - love the use of fairy lights for both colour, oddity and lighting! Nice use of negative space too.', '2006-12-23 07:25:09.000000', NULL, 1),
(3144194, 440654, 3087, '<td valign="top">I do like the photo but I''m at a loss as to why two hammers represent Dogs of War?</td>', 'I do like the photo but I''m at a loss as to why two hammers represent Dogs of War?', '2006-12-23 07:26:55.000000', NULL, 1),
(3144195, 440343, 49773, '<td valign="top">This has a Pink Floyd spirit in it.</td>', 'This has a Pink Floyd spirit in it.', '2006-12-23 07:28:05.000000', NULL, 1),
(3144196, 440058, 3087, '<td valign="top">I think this would fit much better with "Welcome to the Machine"! It''s an interesting commentary on society consuming the people within it, chewing them up and spitting them out! Seems very soft to me but the concept and composition (with angled black and white background/ foreground) is great.</td>', 'I think this would fit much better with "Welcome to the Machine"! It''s an interesting commentary on society consuming the people within it, chewing them up and spitting them out! Seems very soft to me but the concept and composition (with angled black and white background/ foreground) is great.', '2006-12-23 07:29:01.000000', NULL, 1),
(3144197, 440568, 3087, '<td valign="top">The distortion of that textured glass definitely gives a very surreal effect to the facial features and also works well to make the individual anonymous. Interesting idea.</td>', 'The distortion of that textured glass definitely gives a very surreal effect to the facial features and also works well to make the individual anonymous. Interesting idea.', '2006-12-23 07:30:10.000000', NULL, 1),
(3144199, 440327, 3087, '<td valign="top">This is just fabulous! Love the surrealism and simplicity of the idea. The sky behind adds a lovely richness of texture and colour. Great fun!</td>', 'This is just fabulous! Love the surrealism and simplicity of the idea. The sky behind adds a lovely richness of texture and colour. Great fun!', '2006-12-23 07:32:55.000000', NULL, 1),
(3144203, 440636, 3087, '<td valign="top">I can see where you''re going with this, representing the souls with the randomly dispersing swhorls of ink and I do think it''s a clever idea but visually it leaves me feeling something is missing - that it''s not quite there. I can''t put my finger on why. The sky background is nice too though I''d not use blue as one of the two inks infront of it - perhaps red and green inks would be better?</td>', 'I can see where you''re going with this, representing the souls with the randomly dispersing swhorls of ink and I do think it''s a clever idea but visually it leaves me feeling something is missing - that it''s not quite there. I can''t put my finger on why. The sky background is nice too though I''d not use blue as one of the two inks infront of it - perhaps red and green inks would be better?', '2006-12-23 07:35:13.000000', NULL, 1),
(3144204, 440486, 3087, '<td valign="top">Simple. Nice use of negative space. Limited detail works well too. One of the few occasions where the utterly blank white sky is better than a sky with some detail or colour!</td>', 'Simple. Nice use of negative space. Limited detail works well too. One of the few occasions where the utterly blank white sky is better than a sky with some detail or colour!', '2006-12-23 07:36:18.000000', NULL, 1),
(3144208, 439536, 49773, '<td valign="top">I''m really curious why is it so special to be there?</td>', 'I''m really curious why is it so special to be there?', '2006-12-23 07:39:10.000000', NULL, 1),
(3144216, 439227, 3087, '<td valign="top">Nice image! Has a cool retro feel to it and that''s not just the choice to present it in black and white. Something about it reminds of the old silent movies! Central composition and slight distortion of perspective both work well.</td>', 'Nice image! Has a cool retro feel to it and that''s not just the choice to present it in black and white. Something about it reminds of the old silent movies! Central composition and slight distortion of perspective both work well.', '2006-12-23 07:42:44.000000', NULL, 1),
(3144267, 440610, 61155, '<td valign="top">:o) Funny</td>', ':o) Funny', '2006-12-23 08:40:06.000000', NULL, 1),
(3144282, 439246, 61155, '<td valign="top">nicely composed image</td>', 'nicely composed image', '2006-12-23 08:49:37.000000', NULL, 1),
(3144288, 440026, 61155, '<td valign="top">Nice detail/composition.</td>', 'Nice detail/composition.', '2006-12-23 08:51:57.000000', NULL, 1),
(3144292, 440336, 61155, '<td valign="top">?? I don''t see the connection between this image and the song "Money" Sorry</td>', '?? I don''t see the connection between this image and the song "Money" Sorry', '2006-12-23 08:58:43.000000', NULL, 1),
(3144294, 440183, 61155, '<td valign="top">Neat idea. :o) Creative and well composed.</td>', 'Neat idea. :o) Creative and well composed.', '2006-12-23 09:00:22.000000', NULL, 1),
(3144295, 440528, 61155, '<td valign="top">Eeee. Now that''s a face only a mother could love! Good detail and nice catchlight in the eye. Nice blurry bg too.</td>', 'Eeee. Now that''s a face only a mother could love! Good detail and nice catchlight in the eye. Nice blurry bg too.', '2006-12-23 09:01:44.000000', NULL, 1),
(3144302, 440463, 61155, '<td valign="top">Great contrast between the warmth of the sky and the cold frosty dock. Top choice. well done.</td>', 'Great contrast between the warmth of the sky and the cold frosty dock. Top choice. well done.', '2006-12-23 09:22:08.000000', NULL, 1),
(3144318, 439672, 32641, '<td valign="top">Great colours and composition here. The frame is also perfect.</td>', 'Great colours and composition here. The frame is also perfect.', '2006-12-23 09:42:47.000000', NULL, 1),
(3144321, 439844, 32641, '<td valign="top">I am a little puzzled over this one, Why is it Inverted, and what are the dark spots all over?</td>', 'I am a little puzzled over this one, Why is it Inverted, and what are the dark spots all over?', '2006-12-23 09:45:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3144324, 440457, 32641, '<td valign="top">The missing foot is not good, too much clipping I think.</td>', 'The missing foot is not good, too much clipping I think.', '2006-12-23 09:48:37.000000', NULL, 1),
(3144329, 440530, 32641, '<td valign="top">That is a nice pictue, good lighting and composition of the model, but to much dark space on the left.</td>', 'That is a nice pictue, good lighting and composition of the model, but to much dark space on the left.', '2006-12-23 09:51:15.000000', NULL, 1),
