(3144849, 439246, 14773, '<td valign="top">Cool shot but would benefit from more contrast.</td>', 'Cool shot but would benefit from more contrast.', '2006-12-23 16:04:27.000000', NULL, 1),
(3144850, 439737, 14773, '<td valign="top">I''d prefer to see more of the money and less of him -- not that he''s bad looking or anything ... the money just has all this cool texture. 6</td>', 'I''d prefer to see more of the money and less of him -- not that he''s bad looking or anything ... the money just has all this cool texture. 6', '2006-12-23 16:05:18.000000', NULL, 1),
(3144851, 439322, 14773, '<td valign="top">I believe her, she looks pissed. LOL...but a different crop would help and a different outfit...the overall setup and post-processing will probably hurt this image.</td>', 'I believe her, she looks pissed. LOL...but a different crop would help and a different outfit...the overall setup and post-processing will probably hurt this image.', '2006-12-23 16:06:19.000000', NULL, 1),
(3144853, 440548, 14773, '<td valign="top">Like the message but the body itself isn''t selling it to me -- dunno why. And no, you shouldn''t trust the government.</td>', 'Like the message but the body itself isn''t selling it to me -- dunno why. And no, you shouldn''t trust the government.', '2006-12-23 16:07:01.000000', NULL, 1),
(3144855, 438942, 14773, '<td valign="top">Beautiful shot. A little washed out but I like it.</td>', 'Beautiful shot. A little washed out but I like it.', '2006-12-23 16:07:26.000000', NULL, 1),
(3144856, 440490, 65779, '<td valign="top">Have they gone to the mall??</td>', 'Have they gone to the mall??', '2006-12-23 16:08:12.000000', NULL, 1),
(3144857, 439000, 14773, '<td valign="top">Cool except for the background behind the guitar .. the small stuff can kill a good shot.</td>', 'Cool except for the background behind the guitar .. the small stuff can kill a good shot.', '2006-12-23 16:08:48.000000', NULL, 1),
(3144858, 440184, 14773, '<td valign="top">My fave floyd song. The sun is a wee bit bright, like in life..I can''t look directly at it.</td>', 'My fave floyd song. The sun is a wee bit bright, like in life..I can''t look directly at it.', '2006-12-23 16:09:18.000000', NULL, 1),
(3144861, 439053, 14773, '<td valign="top">Don''t take this horribly, but this is just too literal an interpretation for me. .. has a snapshot feel too.</td>', 'Don''t take this horribly, but this is just too literal an interpretation for me. .. has a snapshot feel too.', '2006-12-23 16:10:16.000000', NULL, 1),
(3144863, 439203, 66398, '<td valign="top">The idea is outstanding. The execution however needs improvement. This photo is sort of washed in a yellow hue. The black boots should be black even if you intended the yellow hue for a mood affect. A little less crop at the top so that there were more of the hat showing might have helped too. Overall contrast and color are what drags this one down for me. Keep smiling though because no matter what the score on this photo and no matter what anyone else thinks Daddy will love it when he gets home or if you email it to him.</td>', 'The idea is outstanding. The execution however needs improvement. This photo is sort of washed in a yellow hue. The black boots should be black even if you intended the yellow hue for a mood affect. A little less crop at the top so that there were more of the hat showing might have helped too. Overall contrast and color are what drags this one down for me. Keep smiling though because no matter what the score on this photo and no matter what anyone else thinks Daddy will love it when he gets home or if you email it to him.', '2006-12-23 16:11:04.000000', NULL, 1),
(3144864, 438357, 14773, '<td valign="top">Very literal, yes, but it kind of works although I get no sense of what the meaning should be.  Other than that, the lighting on the mug is a little awkward. 5</td>', 'Very literal, yes, but it kind of works although I get no sense of what the meaning should be.  Other than that, the lighting on the mug is a little awkward. 5', '2006-12-23 16:11:27.000000', NULL, 1),
(3144866, 440456, 14773, '<td valign="top">Wow, she''s selling me ''mad'' like it nobody''s business. 7</td>', 'Wow, she''s selling me ''mad'' like it nobody''s business. 7', '2006-12-23 16:12:10.000000', NULL, 1),
(3144868, 440530, 14773, '<td valign="top">I dig it...nicely done. 7</td>', 'I dig it...nicely done. 7', '2006-12-23 16:12:40.000000', NULL, 1),
(3144869, 440316, 14773, '<td valign="top">Taken from a plane maybe?  A wee bit on the blurry side.</td>', 'Taken from a plane maybe?  A wee bit on the blurry side.', '2006-12-23 16:13:26.000000', NULL, 1),
(3144875, 440462, 14773, '<td valign="top">Great dress but not fond of the lighting...I like her expression but her arm behind her head isn''t flattering..she''s tiny but that arm looks big.</td>', 'Great dress but not fond of the lighting...I like her expression but her arm behind her head isn''t flattering..she''s tiny but that arm looks big.', '2006-12-23 16:16:07.000000', NULL, 1),
(3144877, 440164, 14773, '<td valign="top">Those mountains look so good I could eat ''em..5</td>', 'Those mountains look so good I could eat ''em..5', '2006-12-23 16:16:40.000000', NULL, 1),
