(3145045, 440183, 30896, '<td valign="top">After so many literalisms, this is one I love :-)</td>', 'After so many literalisms, this is one I love :-)', '2006-12-23 17:18:37.000000', NULL, 1),
(3145157, 440590, 15711, '<td valign="top">Great imagination. I think it would even be more effective if his entire chest and neck were mud ridden as well.  Nice focus, DOF and light.</td>', 'Great imagination. I think it would even be more effective if his entire chest and neck were mud ridden as well.  Nice focus, DOF and light.', '2006-12-23 18:43:24.000000', NULL, 1),
(3145165, 440327, 15711, '<td valign="top">Brilliant. 10</td>', 'Brilliant. 10', '2006-12-23 18:47:57.000000', NULL, 1),
(3145171, 439227, 15711, '<td valign="top">You and Dr. No. ha ha ha  This is just fab!! Love the expression, or lack therof. Makes me think of a Charlie Chaplin flick.</td>', 'You and Dr. No. ha ha ha  This is just fab!! Love the expression, or lack therof. Makes me think of a Charlie Chaplin flick.', '2006-12-23 18:50:17.000000', NULL, 1),
(3145172, 440456, 15711, '<td valign="top">This has great intensity.  Love the contrast.  Good one.</td>', 'This has great intensity.  Love the contrast.  Good one.', '2006-12-23 18:51:08.000000', NULL, 1),
(3145281, 440352, 32641, '<td valign="top">Cool picture, looks familiar to me.</td>', 'Cool picture, looks familiar to me.', '2006-12-23 20:01:21.000000', NULL, 1),
(3145282, 438726, 32641, '<td valign="top">Good frame except the right side.</td>', 'Good frame except the right side.', '2006-12-23 20:03:15.000000', NULL, 1),
(3145285, 439053, 32641, '<td valign="top">I am sure you could have done more with this, maybe more blured background.</td>', 'I am sure you could have done more with this, maybe more blured background.', '2006-12-23 20:04:55.000000', NULL, 1),
(3145286, 440644, 32641, '<td valign="top">A nice old wall here :) Like the colours and composition.</td>', 'A nice old wall here :) Like the colours and composition.', '2006-12-23 20:06:35.000000', NULL, 1),
(3145288, 440610, 70270, '<td valign="top">pun intended ...</td>', 'pun intended ...', '2006-12-23 20:08:00.000000', NULL, 1),
(3145348, 440565, 14476, '<td valign="top">Simple and startlingly good.  The color interaction between the orange and green is just splendid.  Well done.  10</td>', 'Simple and startlingly good.  The color interaction between the orange and green is just splendid.  Well done.  10', '2006-12-23 20:52:05.000000', NULL, 1),
(3145386, 440605, 36006, '<td valign="top">zoomdack?? c''mon man, haven''t you had enough of this beach?<br/> <br/>If not zoomdack, disregard.</td>', 'zoomdack?? c''mon man, haven''t you had enough of this beach? If not zoomdack, disregard.', '2006-12-23 21:15:29.000000', NULL, 1),
