INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3151328, 440327, 52549, '<td valign="top">Great shot Tate. Congrats on the blue.</td>', 'Great shot Tate. Congrats on the blue.', '2006-12-27 00:35:41.000000', NULL, 0),
(3151345, 440327, 7628, '<td valign="top">Almost unbelievable serendipity - no strings? no tripod? wind!? _coincidently_ wore black?!! The gods are with you - this shot looks like every aspect had been planned and executed to within millimeters. <br/>And oops - I faved it - Maybe you can dig up some more brain cells for science - but not just yet.  Use them while you can here at DPC we all sure enjoy seeing the results!</td>', 'Almost unbelievable serendipity - no strings? no tripod? wind!? _coincidently_ wore black?!! The gods are with you - this shot looks like every aspect had been planned and executed to within millimeters. And oops - I faved it - Maybe you can dig up some more brain cells for science - but not just yet.  Use them while you can here at DPC we all sure enjoy seeing the results!', '2006-12-27 00:38:00.000000', NULL, 0),
(3151347, 439227, 52549, '<td valign="top">You juggle with bowling balls? ;-))) Great shot Tim, really great. Congrats on top 5.</td>', 'You juggle with bowling balls? ;-))) Great shot Tim, really great. Congrats on top 5.', '2006-12-27 00:38:14.000000', NULL, 0),
(3151357, 439227, 41337, '<td valign="top">This was such a great take to the challenge. One of my top picks.</td>', 'This was such a great take to the challenge. One of my top picks.', '2006-12-27 00:38:47.000000', NULL, 0),
(3151367, 440026, 61818, '<td valign="top">This was really nice, grats on the good score!</td>', 'This was really nice, grats on the good score!', '2006-12-27 00:40:03.000000', NULL, 0),
(3151377, 439227, 50231, '<td valign="top">Great finish Tim! One out man so close! Untouchables do rule!</td>', 'Great finish Tim! One out man so close! Untouchables do rule!', '2006-12-27 00:41:04.000000', NULL, 0),
(3151387, 440460, 15497, '<td valign="top">Nice to see you back, this is a stunning photo with a lot of impact.<br/></td>', 'Nice to see you back, this is a stunning photo with a lot of impact.', '2006-12-27 00:42:15.000000', NULL, 0),
