(3161387, 440460, 16241, '<td valign="top">i like it, black white may also be good.</td>', 'i like it, black white may also be good.', '2006-12-30 00:32:55.000000', NULL, 0),
(3162163, 440610, 5885, '<td valign="top">LOL, nice lighting :-)</td>', 'LOL, nice lighting :-)', '2006-12-30 12:57:49.000000', NULL, 0),
(3162306, 438882, 56332, '<td valign="top">what can i say? shots i put effort into, shots i wanted to say something to the viewer: dnmc, don''t get it, doesn''t scream whatever to me, etc. cheesiest, most mundane shot i ever took (i''m talking about the peacock one) gets the red ribbon. i''m proud though that some of my lowest scoring images were selected as someone''s favorites and got some nice comments. at least there are still SOME out there that "get it".</td>', 'what can i say? shots i put effort into, shots i wanted to say something to the viewer: dnmc, don''t get it, doesn''t scream whatever to me, etc. cheesiest, most mundane shot i ever took (i''m talking about the peacock one) gets the red ribbon. i''m proud though that some of my lowest scoring images were selected as someone''s favorites and got some nice comments. at least there are still SOME out there that "get it".', '2006-12-30 14:16:03.000000', NULL, 0),
(3162349, 440037, 22459, '<td valign="top">Congrats on the ribbon. This is a fantastic image that would stand alone without the challenge.</td>', 'Congrats on the ribbon. This is a fantastic image that would stand alone without the challenge.', '2006-12-30 14:42:04.000000', NULL, 0),
(3162990, 440604, 68504, '<td valign="top">Delightful photo. Love the way you carried out the concept - this is always satisfying.</td>', 'Delightful photo. Love the way you carried out the concept - this is always satisfying.', '2006-12-30 20:21:34.000000', NULL, 0),
